import {
  isHalfKey,
  isQuarterKey,
  normalizeTimePeriodType,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

/**
 * Reduces granular Volume card period types to the canonical Time Period
 * contract used by filters and display calculations.
 */
export function getCanonicalVolumeTimePeriodType(
  periodType: string | null | undefined,
): TimePeriodType | null {
  if (!periodType) return null;

  const normalized = periodType.trim().toUpperCase();
  if (isHalfKey(normalized)) return TimePeriodType.HALF;
  if (isQuarterKey(normalized)) return TimePeriodType.QTR;

  return normalizeTimePeriodType(normalized) || null;
}
